function parseItems(text){ var lines=(text||'').split(/\n+/); var items=[];
  for(var i=0;i<lines.length;i++){ var p=lines[i].trim(); if(!p) continue;
    var parts=p.split(/(,|\t|，)/); if(parts.length<2) continue;
    var name=parts[0].trim(); var rest=parts.slice(1).join('').trim();
    var num=parseFloat(rest.replace(/[^0-9.\-]/g,'')); if(isNaN(num)) continue;
    var cycle=/y/i.test(rest)?'yearly':'monthly';
    items.push({name:name, amount:num, cycle:cycle}); }
  return items; }
function totals(items){ var m=0; for(var i=0;i<items.length;i++){ var it=items[i]; if(it.cycle==='yearly') m+=it.amount/12; else m+=it.amount; }
  return {monthly:Math.round(m*100)/100, yearly:Math.round(m*12*100)/100, count:items.length}; }
var EXPORTS={parseItems:parseItems, totals:totals};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.SubscriptionForgePure = EXPORTS; }
